eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   editorialCopy: () => (/* binding */ editorialCopy)\n/* harmony export */ });\nconst editorialCopy = {\n    \"fa\": {\n        \"cmsError\": \"محتوای تازه دریافت نشد.\",\n        \"cmsRetry\": \"تلاش دوباره\",\n        \"cmsRead\": \"بیشتر بخوانید\",\n        \"cmsTitle\": \"تازه‌های مجموعه\",\n        \"account\": \"حساب کاربری\",\n        \"collection\": \"مجموعهٔ هما نت\",\n        \"utility\": \"از ایران، با نگاهی جهانی\",\n        \"partnership\": \"همکاری با ما\",\n        \"introLabel\": \"دربارهٔ همای\",\n        \"introTitle\": \"یک باشگاه،\\nهمهٔ خدمات همای.\",\n        \"introText\": \"هما نت در زمینهٔ گردشگری، صنایع‌دستی، محصولات چرمی، زیبایی و فناوری فعالیت می‌کند. با عضویت در باشگاه مشتریان، از همهٔ این خدمات با مزایای ویژهٔ اعضا استفاده می‌کنید و سفارش‌ها و درخواست‌هایتان را در یک حساب کاربری پیگیری می‌کنید.\",\n        \"introLink\": \"آشنایی با هما نت\",\n        \"journeyLabel\": \"سفر، به روایت شما\",\n        \"journeyTitle\": \"ایران را نزدیک‌تر ببینید.\",\n        \"journeyIntro\": \"از قدم‌زدن در شهر تا دیدن هنر در کارگاه؛ علاقه‌تان را انتخاب کنید تا گفت‌وگو دربارهٔ سفر از همان‌جا شروع شود.\",\n        \"isfahan\": \"معماری و شهر\",\n        \"shiraz\": \"هنر و کارگاه\",\n        \"yazd\": \"زندگی و فرهنگ\",\n        \"isfahanTitle\": \"میدان، بازار، مکث.\",\n        \"shirazTitle\": \"از نزدیک، کنار هنر دست.\",\n        \"yazdTitle\": \"فرصتی برای دیدن زندگی.\",\n        \"isfahanText\": \"برای علاقه‌مندان به معماری، عکاسی و صنایع‌دستی؛ نقطهٔ شروعی برای برنامه‌ریزی سفری که زمان کافی برای دیدن دارد.\",\n        \"shirazText\": \"اگر دیدن مراحل ساخت یک اثر برایتان جذاب است، علاقه‌تان به هنر و کارگاه را در درخواست سفر بنویسید.\",\n        \"yazdText\": \"برای تجربهٔ فضاهای شهری و آشنایی با فرهنگ روزمره، از ریتم سفر و علاقه‌های شخصی‌تان بگویید.\",\n        \"journeyAction\": \"دربارهٔ این سفر گفت‌وگو کنیم\",\n        \"journeyNote\": \"ایدهٔ سفر؛ برنامه و امکان اجرا پس از بررسی درخواست مشخص می‌شود.\",\n        \"craftLabel\": \"اشیایی با قصه\",\n        \"craftTitle\": \"هنر دست، برای زندگی امروز.\",\n        \"craftText\": \"به رنگ، بافت و رد دست سازنده نگاه کنید. برای انتخاب یک اثر شخصی یا هدیهٔ سازمانی، از سلیقه و کاربرد مورد نظرتان شروع می‌کنیم.\",\n        \"craftAction\": \"درخواست انتخاب اثر\",\n        \"craftCaption\": \"رنگ، بافت و جزئیات؛ زبان مشترک یک اثر.\",\n        \"beautyLabel\": \"زیبایی و مراقبت\",\n        \"beautyTitle\": \"زمانی برای خودتان.\",\n        \"beautyText\": \"انتخاب محصولات و تجربه‌های مراقبتی از شناخت سلیقه و نیاز شما شروع می‌شود. دربارهٔ چیزی که دنبالش هستید بنویسید تا درخواستتان در مسیر مرتبط بررسی شود.\",\n        \"beautyAction\": \"کشف دنیای زیبایی\",\n        \"studioLabel\": \"استودیو خلاق\",\n        \"studioTitle\": \"از یک ایده\\nتا روایتی دیدنی.\",\n        \"studioText\": \"برای برندهایی که حرفی برای گفتن دارند؛ از جهت بصری و محتوای چندزبانه تا بررسی کاربرد ابزارهای هوشمند در جریان کار.\",\n        \"studioAction\": \"دربارهٔ پروژه‌تان بگویید\",\n        \"studioService1\": \"هویت و روایت بصری\",\n        \"studioService2\": \"محتوای چندزبانه\",\n        \"studioService3\": \"فرآیندهای هوشمند\",\n        \"journalLabel\": \"دفتر هما نت\",\n        \"journalTitle\": \"چیزهایی که ارزش دیدن دارند.\",\n        \"read\": \"خواندن یادداشت\",\n        \"journal1Title\": \"سفر خوب، جایی برای مکث دارد.\",\n        \"journal1Tag\": \"یادداشت سفر\",\n        \"journal1Body\": \"برای برنامه‌ریزی سفر لازم نیست همهٔ ساعت‌ها را پر کنیم. گاهی یک صبح آزاد، فرصت دیدن جزئیاتی را می‌دهد که در مسیرهای شلوغ از دست می‌روند. پیش از انتخاب مقصد، از خودمان بپرسیم دوست داریم در سفر چه احساسی داشته باشیم: آرامش، کشف یا همراهی؟ پاسخ همین پرسش، شروع بهتری برای گفت‌وگو دربارهٔ مسیر است.\",\n        \"journal2Title\": \"هدیه‌ای که فقط زیبا نیست.\",\n        \"journal2Tag\": \"هنر و زندگی\",\n        \"journal2Body\": \"یک هدیهٔ دست‌ساز با رنگ و شکلش آغاز می‌شود، اما انتخاب خوب به آدمی که آن را دریافت می‌کند هم فکر می‌کند. کاربرد روزمره، فضای خانه و سلیقهٔ او، به اندازهٔ ظاهر اثر مهم‌اند. برای سفارش هدیهٔ سازمانی هم بهتر است تعداد، زمان مورد نیاز و شیوهٔ بسته‌بندی از ابتدا روشن باشند.\",\n        \"journal3Title\": \"جزئیات کوچک، روایت بزرگ.\",\n        \"journal3Tag\": \"نگاه خلاق\",\n        \"journal3Body\": \"پیش از انتخاب رنگ یا ساختن تصویر، باید بدانیم با چه کسی حرف می‌زنیم. یک روایت منسجم از شناخت مخاطب، هدف روشن و انتخاب دقیق جزئیات شکل می‌گیرد. ابزارها می‌توانند کار را سریع‌تر کنند؛ اما لحن، معنا و کیفیت نهایی به تصمیم‌های سنجیده نیاز دارند.\",\n        \"businessLabel\": \"همکاری تجاری\",\n        \"businessTitle\": \"همکاری خوب،\\nاز گفت‌وگوی خوب شروع می‌شود.\",\n        \"businessText\": \"برای همکاری در گردشگری، معرفی آثار، هدایای سازمانی یا پروژه‌های محتوا، زمینهٔ فعالیت و نیازتان را بنویسید. درخواست شما با موضوع مشخص ثبت و قابل پیگیری می‌شود.\",\n        \"businessAction\": \"ثبت درخواست همکاری\",\n        \"processTitle\": \"از آشنایی تا قدم بعدی\",\n        \"process1\": \"علاقه‌تان را انتخاب کنید\",\n        \"process1Body\": \"حوزه، مقصد یا ایده‌ای را که در ذهن دارید مشخص کنید.\",\n        \"process2\": \"جزئیات را با ما در میان بگذارید\",\n        \"process2Body\": \"زمان، نیازها و اولویت‌ها را در درخواست بنویسید.\",\n        \"process3\": \"درخواستتان را پیگیری کنید\",\n        \"process3Body\": \"رسید را نگه دارید و وضعیت بررسی را با کد خصوصی ببینید.\",\n        \"footerTitle\": \"در ارتباط بمانیم.\",\n        \"footerText\": \"برای یک پرسش، یک سفر یا شروع همکاری؛ از همین‌جا به ما بگویید.\",\n        \"footerContact\": \"گفت‌وگو با هما نت\",\n        \"footerIdentity\": \"سفر · زیبایی · فرهنگ · خلاقیت\",\n        \"viewAll\": \"همهٔ حوزه‌ها\",\n        \"discover\": \"کشف کنید\"\n    },\n    \"en\": {\n        \"cmsError\": \"Updates could not be loaded.\",\n        \"cmsRetry\": \"Try again\",\n        \"cmsRead\": \"Read more\",\n        \"cmsTitle\": \"Latest from Homanet\",\n        \"account\": \"My account\",\n        \"collection\": \"The Homanet collection\",\n        \"utility\": \"Rooted in Iran. Open to the world.\",\n        \"partnership\": \"Partner with us\",\n        \"introLabel\": \"ABOUT HOMA\",\n        \"introTitle\": \"One club.\\nEvery Homa service.\",\n        \"introText\": \"Homanet works across travel, handicrafts, leather goods, beauty and technology. As a member of the customers club, you use all of these services with member benefits and follow your orders and requests from a single account.\",\n        \"introLink\": \"Meet Homanet\",\n        \"journeyLabel\": \"TRAVEL, YOUR WAY\",\n        \"journeyTitle\": \"A closer look at Iran.\",\n        \"journeyIntro\": \"From a walk through the city to time in a craft workshop. Choose what draws you in, and let that be the beginning of a conversation about your journey.\",\n        \"isfahan\": \"Architecture and city life\",\n        \"shiraz\": \"Craft & workshops\",\n        \"yazd\": \"Life & culture\",\n        \"isfahanTitle\": \"A square. A bazaar. A slower pace.\",\n        \"shirazTitle\": \"Closer to the making.\",\n        \"yazdTitle\": \"Time to notice everyday life.\",\n        \"isfahanText\": \"For an interest in architecture, photography and craftsmanship. A starting point for a journey with time to notice the details.\",\n        \"shirazText\": \"Interested in how an object takes shape? Include your interest in craft and workshops in your travel enquiry.\",\n        \"yazdText\": \"For an interest in city spaces and everyday culture, tell us about the pace and experiences you have in mind.\",\n        \"journeyAction\": \"Enquire about this journey\",\n        \"journeyNote\": \"Travel inspiration; itinerary and availability are confirmed after review.\",\n        \"craftLabel\": \"OBJECTS WITH A STORY\",\n        \"craftTitle\": \"Made by hand. Chosen for life.\",\n        \"craftText\": \"Look at the colour, the texture, the hand behind the work. Whether you are considering a personal piece or a business gift, start with how you want it to feel and where it will belong.\",\n        \"craftAction\": \"Discuss a piece\",\n        \"craftCaption\": \"Colour, texture and detail. The language of a piece.\",\n        \"beautyLabel\": \"Beauty and care\",\n        \"beautyTitle\": \"A little time for yourself.\",\n        \"beautyText\": \"Thoughtful care begins with understanding your preferences. Tell us what you are looking for so your enquiry can be reviewed in the right context.\",\n        \"beautyAction\": \"Explore beauty & care\",\n        \"studioLabel\": \"THE CREATIVE STUDIO\",\n        \"studioTitle\": \"From a first thought\\nto something worth seeing.\",\n        \"studioText\": \"For brands with something to say. Explore visual direction, multilingual content and the considered use of intelligent tools in your creative workflow.\",\n        \"studioAction\": \"Tell us about your project\",\n        \"studioService1\": \"Visual identity and storytelling\",\n        \"studioService2\": \"Multilingual content\",\n        \"studioService3\": \"Intelligent workflows\",\n        \"journalLabel\": \"THE JOURNAL\",\n        \"journalTitle\": \"Worth a closer look.\",\n        \"read\": \"Read the note\",\n        \"journal1Title\": \"A good journey leaves time to pause.\",\n        \"journal1Tag\": \"TRAVEL NOTES\",\n        \"journal1Body\": \"A well-planned journey does not need to fill every hour. An open morning can leave space for the details a hurried itinerary misses. Before choosing a route, ask what you would like the journey to feel like: restful, curious, shared? That answer is often a useful place to begin.\",\n        \"journal2Title\": \"A gift with something to say.\",\n        \"journal2Tag\": \"CRAFT & LIVING\",\n        \"journal2Body\": \"A handmade gift begins with colour and form, but a thoughtful choice also considers the person receiving it. Everyday use, their home and their preferences matter as much as appearance. For a business gifting enquiry, include the quantity, timing and packaging you have in mind.\",\n        \"journal3Title\": \"Small details, a clearer story.\",\n        \"journal3Tag\": \"CREATIVE PERSPECTIVES\",\n        \"journal3Body\": \"Before selecting a colour or making an image, know who you are speaking to. A coherent story begins with an audience, a clear purpose and a considered choice of details. Tools can make the work faster; voice, meaning and the final quality still depend on deliberate decisions.\",\n        \"businessLabel\": \"FOR BUSINESSES\",\n        \"businessTitle\": \"Good partnerships\\nbegin with a conversation.\",\n        \"businessText\": \"For travel partnerships, craft sourcing, business gifts or content projects, tell us about your organisation and what you need. Your enquiry will be recorded with a private reference for follow-up.\",\n        \"businessAction\": \"Discuss a partnership\",\n        \"processTitle\": \"A clear next step\",\n        \"process1\": \"Choose your interest\",\n        \"process1Body\": \"Start with the experience, destination or idea you have in mind.\",\n        \"process2\": \"Tell us the details\",\n        \"process2Body\": \"Include your timing, needs and priorities in the enquiry.\",\n        \"process3\": \"Follow your enquiry\",\n        \"process3Body\": \"Keep your receipt and use its private code to check the review status.\",\n        \"footerTitle\": \"Let’s stay connected.\",\n        \"footerText\": \"A question, a journey, a new collaboration. Tell us where you would like to begin.\",\n        \"footerContact\": \"Speak with Homanet\",\n        \"footerIdentity\": \"TRAVEL · BEAUTY · CULTURE · CREATIVITY\",\n        \"viewAll\": \"All sectors\",\n        \"discover\": \"Discover\"\n    },\n    \"ar\": {\n        \"cmsError\": \"تعذر تحميل المستجدات.\",\n        \"cmsRetry\": \"حاول مجدداً\",\n        \"cmsRead\": \"اقرأ المزيد\",\n        \"cmsTitle\": \"آخر المستجدات\",\n        \"account\": \"حسابي\",\n        \"collection\": \"مجموعة هما نت\",\n        \"utility\": \"من إيران، برؤية عالمية\",\n        \"partnership\": \"تعاون معنا\",\n        \"introLabel\": \"عن همای\",\n        \"introTitle\": \"نادٍ واحد.\\nكل خدمات هماي.\",\n        \"introText\": \"تعمل هما نت في مجالات السياحة والحرف اليدوية والمنتجات الجلدية والجمال والتكنولوجيا. بعضويتك في نادي العملاء تستفيد من جميع هذه الخدمات بمزايا خاصة بالأعضاء، وتتابع طلباتك واستفساراتك من حساب واحد.\",\n        \"introLink\": \"تعرّف إلى هما نت\",\n        \"journeyLabel\": \"السفر بطريقتك\",\n        \"journeyTitle\": \"اكتشف إيران عن قرب.\",\n        \"journeyIntro\": \"من جولة في المدينة إلى زيارة ورشة حرفية. اختر ما يثير اهتمامك لنبدأ الحديث عن رحلتك.\",\n        \"isfahan\": \"العمارة والمدينة\",\n        \"shiraz\": \"الحرف والورش\",\n        \"yazd\": \"الحياة والثقافة\",\n        \"isfahanTitle\": \"ساحة، سوق، ولحظة تأمل.\",\n        \"shirazTitle\": \"عن قرب، مع الحِرفة.\",\n        \"yazdTitle\": \"وقت لاكتشاف تفاصيل الحياة.\",\n        \"isfahanText\": \"لمهتمّي العمارة والتصوير والحرف؛ بداية لرحلة تمنحك وقتاً لملاحظة التفاصيل.\",\n        \"shirazText\": \"هل يهمك التعرف إلى مراحل صناعة قطعة يدوية؟ أخبرنا عن اهتمامك بالحرف والورش في طلب رحلتك.\",\n        \"yazdText\": \"إذا كنت مهتماً بالمدينة وثقافتها اليومية، أخبرنا بإيقاع الرحلة والتجارب التي تفضلها.\",\n        \"journeyAction\": \"استفسر عن هذه الرحلة\",\n        \"journeyNote\": \"فكرة للسفر؛ يُحدّد البرنامج والتوافر بعد مراجعة الطلب.\",\n        \"craftLabel\": \"قطع تحمل حكاية\",\n        \"craftTitle\": \"صُنعت باليد، لترافق الحياة.\",\n        \"craftText\": \"تأمّل اللون والملمس وأثر يد الصانع. لاختيار قطعة شخصية أو هدية مؤسسية، نبدأ بذوقك وطريقة استخدامها.\",\n        \"craftAction\": \"استفسر عن قطعة\",\n        \"craftCaption\": \"اللون والملمس والتفاصيل؛ لغة القطعة.\",\n        \"beautyLabel\": \"الجمال والعناية\",\n        \"beautyTitle\": \"وقتٌ لنفسك.\",\n        \"beautyText\": \"تبدأ العناية بفهم تفضيلاتك. أخبرنا عمّا تبحث عنه لتُراجع رغبتك في السياق المناسب.\",\n        \"beautyAction\": \"اكتشف عالم الجمال\",\n        \"studioLabel\": \"الاستوديو الإبداعي\",\n        \"studioTitle\": \"من فكرة أولى\\nإلى حكاية تستحق المشاهدة.\",\n        \"studioText\": \"للعلامات التي تحمل رسالة؛ من التوجّه البصري والمحتوى متعدد اللغات إلى الاستخدام المدروس للأدوات الذكية.\",\n        \"studioAction\": \"حدّثنا عن مشروعك\",\n        \"studioService1\": \"التوجّه البصري\",\n        \"studioService2\": \"محتوى متعدد اللغات\",\n        \"studioService3\": \"عمليات ذكية\",\n        \"journalLabel\": \"دفتر هما نت\",\n        \"journalTitle\": \"تستحق نظرة أقرب.\",\n        \"read\": \"اقرأ المقال\",\n        \"journal1Title\": \"اترك مساحة للمفاجأة.\",\n        \"journal1Tag\": \"ملاحظات سفر\",\n        \"journal1Body\": \"لا تحتاج الرحلة المدروسة إلى ملء كل ساعة. صباح بلا جدول قد يتيح ملاحظة تفاصيل يفوتها المسار المتعجل. قبل اختيار الطريق، اسأل نفسك: هل تريد الهدوء، أم الاكتشاف، أم المشاركة؟ الإجابة بداية مناسبة للتخطيط.\",\n        \"journal2Title\": \"هدية تحمل معنى.\",\n        \"journal2Tag\": \"الحرفة والحياة\",\n        \"journal2Body\": \"تبدأ الهدية اليدوية باللون والشكل، لكن الاختيار المدروس يراعي من يتلقّاها أيضاً. الاستخدام اليومي والمنزل والذوق مهمة بقدر المظهر. لطلب هدايا مؤسسية، حدّد العدد والموعد والتغليف المطلوب.\",\n        \"journal3Title\": \"تفاصيل صغيرة، حكاية أوضح.\",\n        \"journal3Tag\": \"رؤى إبداعية\",\n        \"journal3Body\": \"قبل اختيار لون أو صناعة صورة، اعرف من تخاطب. تبدأ الحكاية المتماسكة بجمهور وهدف واضح وتفاصيل مختارة بعناية. قد تسرّع الأدوات العمل، لكن النبرة والمعنى والجودة تحتاج قرارات مدروسة.\",\n        \"businessLabel\": \"للشركات\",\n        \"businessTitle\": \"يبدأ التعاون الجيد\\nبحوار جيد.\",\n        \"businessText\": \"للتعاون السياحي أو الأعمال الحرفية أو الهدايا المؤسسية أو مشاريع المحتوى، أخبرنا عن مؤسستك واحتياجك. يُسجّل طلبك برمز خاص للمتابعة.\",\n        \"businessAction\": \"ناقش فرصة تعاون\",\n        \"processTitle\": \"خطوة تالية واضحة\",\n        \"process1\": \"اختر اهتمامك\",\n        \"process1Body\": \"ابدأ بالتجربة أو الوجهة أو الفكرة التي في ذهنك.\",\n        \"process2\": \"شاركنا التفاصيل\",\n        \"process2Body\": \"اذكر الموعد والاحتياجات والأولويات في طلبك.\",\n        \"process3\": \"تابع طلبك\",\n        \"process3Body\": \"احتفظ بالإيصال واستخدم رمزه الخاص لمعرفة حالة المراجعة.\",\n        \"footerTitle\": \"لنبقَ على تواصل.\",\n        \"footerText\": \"لسؤال أو رحلة أو تعاون جديد، أخبرنا من أين تريد أن تبدأ.\",\n        \"footerContact\": \"تواصل مع هما نت\",\n        \"footerIdentity\": \"سفر · جمال · ثقافة · إبداع\",\n        \"viewAll\": \"كل مجالاتنا\",\n        \"discover\": \"اكتشف\"\n    }\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./app/editorial-copy.ts\n");

